import csv
import io


def parse_csv(raw_csv: str):
    expected_width = 11
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    records = list(csv.reader(io.StringIO(raw_csv, newline=""),
                              delimiter=",", quotechar='"', doublequote=True))

    def has_content(row):
        return any(cell.strip() for cell in row)

    def is_grouped_header(upper, lower):
        if len(upper) != expected_width or len(lower) != expected_width:
            return False
        if upper[0].strip() or lower[0].strip():
            return False

        groups = []
        for parent, child in zip(upper[1:], lower[1:]):
            parent, child = parent.strip(), child.strip()
            if parent and (not groups or parent != groups[-1][0]):
                groups.append((parent, []))
            if not groups or not child:
                return False
            groups[-1][1].append(child)

        if len(groups) < 2:
            return False
        pattern = groups[0][1]
        return (
            len(pattern) >= 2
            and len(set(pattern)) == len(pattern)
            and all(children == pattern for _, children in groups)
        )

    if not any(has_content(row) for row in records):
        return {"columns": [], "rows": []}

    for i in range(len(records) - 1):
        if not is_grouped_header(records[i], records[i + 1]):
            continue

        upper, lower = records[i], records[i + 1]
        start = i + 2
        index_name = "column_1"
        if start < len(records):
            candidate = records[start]
            if (
                len(candidate) == len(upper)
                and candidate[0].strip()
                and all(not cell.strip() for cell in candidate[1:])
            ):
                index_name = candidate[0]
                start += 1

        columns = [index_name]
        parent = ""
        for label, child in zip(upper[1:], lower[1:]):
            if label.strip():
                parent = label
            columns.append(parent + "_" + child)
        break
    else:
        start = next(
            (i for i, row in enumerate(records)
             if len(row) == expected_width and has_content(row)),
            None,
        )
        if start is None:
            start = next(i for i, row in enumerate(records) if has_content(row))
        columns = records[start][:]
        start += 1

    rows = records[start:]
    width = max([expected_width, len(columns)] + [len(row) for row in rows])
    columns.extend([""] * (width - len(columns)))

    reserved = {name for name in columns if name.strip()}
    used = set()
    for i, name in enumerate(columns):
        if name.strip() and name not in used:
            used.add(name)
            continue
        base = name if name.strip() else f"column_{i + 1}"
        candidate = base
        suffix = 2
        while candidate in reserved or candidate in used:
            candidate = f"{base}_{suffix}"
            suffix += 1
        columns[i] = candidate
        used.add(candidate)

    return {
        "columns": columns,
        "rows": [row + [""] * (width - len(row)) for row in rows],
    }
